import hashlib
import itertools
import multiprocessing
import string

def generate_candidates(charset, min_len, max_len):
    for length in range(min_len, max_len + 1):
        for combination in itertools.product(charset, repeat=length):
            yield ''.join(combination)

def hash_and_check(plaintext, target_hash):
    hash_object = hashlib.sha256(plaintext.encode())
    computed_hash = hash_object.hexdigest()
    return computed_hash == target_hash, plaintext

def worker_function(task_queue, result_queue, target_hash):
    while not task_queue.empty():
        candidate = task_queue.get()
        is_match, match = hash_and_check(candidate, target_hash)
        if is_match:
            result_queue.put(match)
            return  # Stop further processing when match is found

def main():
    target_hash = "a60458d2180258d47d7f7bef5236b33e86711ac926518ca4545ebf24cdc0b76c"
    charset = string.ascii_lowercase
    min_len = 1
    max_len = 6

    task_queue = multiprocessing.Queue()
    result_queue = multiprocessing.Queue()

    for candidate in generate_candidates(charset, min_len, max_len):
        task_queue.put(candidate)

    processes = []
    cpu_count = multiprocessing.cpu_count()
    for _ in range(cpu_count):
        process = multiprocessing.Process(target=worker_function, args=(task_queue, result_queue, target_hash))
        processes.append(process)
        process.start()

    for process in processes:
        process.join()

    if not result_queue.empty():
        match = result_queue.get()
        print(f"Found match: {match}")
    else:
        print("No match found.")

if __name__ == "__main__":
    main()
